class Parent {
  Parent() { init(); }
  void init() { System.out.println("parent-init"); }
}
class Child extends Parent {
  int value = 7;
  @Override void init() { System.out.println("child-init value=" + value); }
}
class Main {
  public static void main(String[] args) {
    new Child();
  }
}

